export type PDFFormField={id:string;label:string;pageId:string;required:boolean;readOnly:boolean;error?:string}&(
 {kind:'text';value:string;maxLength:number;multiline?:boolean}|
 {kind:'checkbox';value:boolean}|
 {kind:'choice';value:string;options:readonly {id:string;label:string;disabled?:boolean}[]}|
 {kind:'signature';signed:boolean;signerLabel?:string});
export interface PDFFormFieldEditorProps extends Omit<ViewProps,'children'>,ScopedControlProps {
 fields:readonly PDFFormField[];selectedId:string|null;onSelect:(id:string,pageId:string)=>void;
 onCommit:(id:string,value:PropertyValue,signal?:AbortSignal)=>unknown;
 onSign:(id:string,signal?:AbortSignal)=>unknown;onValidate:(signal?:AbortSignal)=>unknown;
 validationStatus:'unvalidated'|'validating'|'valid'|'invalid';validationRevision?:string|number;unstyled?:boolean;
}
/** Edits actual AcroForm metadata; native signing, field appearance regeneration and validation stay with the PDF host. */
export function PDFFormFieldEditor({scope='pdf-form',revision=0,...props}:PDFFormFieldEditorProps){
 const {fields,selectedId,onSelect:_select,onCommit:_commit,onSign:_sign,onValidate:_validate,validationStatus,validationRevision,unstyled=false,disabledReason,style,...rest}=props;
 if(fields.length>100000||new Set(fields.map(f=>f.id)).size!==fields.length||fields.some(f=>!f.id.trim()||!f.pageId.trim()||!f.label.trim()||f.label.length>1024||f.kind==='text'&&(!Number.isInteger(f.maxLength)||f.maxLength<1||f.maxLength>65536||f.value.length>f.maxLength)||f.kind==='choice'&&(f.options.length>512||new Set(f.options.map(o=>o.id)).size!==f.options.length)))throw new RangeError('Invalid PDF form fields');
 const owner=JSON.stringify([...controlIdentity(scope,revision),disabledReason]),guard=useScopedControl(owner,props,disabledReason!==undefined||validationStatus==='validating'),off=guard.pending||disabledReason!==undefined||validationStatus==='validating',selected=fields.find(f=>f.id===selectedId);
 const schema:InspectorProperty[]=selected&&selected.kind!=='signature'?[selected.kind==='text'?{kind:'text',id:selected.id,label:selected.label,value:selected.value,maxLength:selected.maxLength,multiline:selected.multiline}:selected.kind==='checkbox'?{kind:'boolean',id:selected.id,label:selected.label,value:selected.value}:{kind:'choice',id:selected.id,label:selected.label,value:selected.value,choices:selected.options}]:[];
